namespace Microsoft.UI.Xaml.Markup.Compiler.FileIO
{
    using System;
    using System.IO;
    using System.Runtime.InteropServices.Marshalling;
    using Windows.Win32.Foundation;
    using Windows.Win32.System.Com;

    /// <summary>
    /// A XAML input or XBF output stream of GenXbf.dll, which gets it as a COM IStream (source-generated COM; the interfaces are
    /// generated by CsWin32, see NativeMethods.txt). The members GenXbf.dll doesn't use throw NotImplementedException, which is
    /// returned to native code as E_NOTIMPL.
    /// </summary>
    [GeneratedComClass]
    internal partial class StreamImpl : IStream, IDisposable
    {
        private bool _disposed;
        protected Stream _underlyingStream;

        public void Write(byte[] buffer)
        {
            Write(buffer.AsSpan());
        }

        public void Write(ReadOnlySpan<byte> buffer)
        {
            if (!_underlyingStream.CanWrite)
            {
                throw new InvalidOperationException();
            }
            _underlyingStream.Write(buffer);
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (!_disposed)
            {
                if (disposing)
                {
                    _underlyingStream.Dispose();
                    _underlyingStream = null;
                }
                _disposed = true;
            }
        }

        unsafe HRESULT ISequentialStream.Read(void* pv, uint cb, uint* pcbRead)
        {
            if (!_underlyingStream.CanRead)
            {
                throw new InvalidOperationException();
            }
            int cntRead = _underlyingStream.Read(new Span<byte>(pv, checked((int)cb)));
            if (pcbRead != null)
            {
                *pcbRead = (uint)cntRead;
            }
            return default; // S_OK
        }

        unsafe HRESULT ISequentialStream.Write(void* pv, uint cb, uint* pcbWritten)
        {
            Write(new ReadOnlySpan<byte>(pv, checked((int)cb)));
            if (pcbWritten != null)
            {
                *pcbWritten = cb;
            }
            return default; // S_OK
        }

        unsafe void IStream.Seek(long dlibMove, SeekOrigin dwOrigin, ulong* plibNewPosition)
        {
            if (!_underlyingStream.CanSeek)
            {
                throw new InvalidOperationException();
            }
            long newPos = _underlyingStream.Seek(dlibMove, dwOrigin);
            if (plibNewPosition != null)
            {
                *plibNewPosition = (ulong)newPos;
            }
        }

        void IStream.SetSize(ulong libNewSize)
        {
            _underlyingStream.SetLength(checked((long)libNewSize));
        }

        unsafe void IStream.CopyTo(IStream pstm, ulong cb, ulong* pcbRead, ulong* pcbWritten) => throw new NotImplementedException();

        void IStream.Commit(STGC grfCommitFlags) => throw new NotImplementedException();

        void IStream.Revert() => throw new NotImplementedException();

        void IStream.LockRegion(ulong libOffset, ulong cb, LOCKTYPE dwLockType) => throw new NotImplementedException();

        void IStream.UnlockRegion(ulong libOffset, ulong cb, uint dwLockType) => throw new NotImplementedException();

        unsafe void IStream.Stat(STATSTG* pstatstg, STATFLAG grfStatFlag) => throw new NotImplementedException();

        void IStream.Clone(out IStream ppstm) => throw new NotImplementedException();
    }
